import{_ as s,o as t,c as i,a2 as n}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"Pipelines","description":"","frontmatter":{},"headers":[],"relativePath":"pipelines.md","filePath":"pipelines.md"}'),a={name:"pipelines.md"};function o(d,e,l,r,p,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="pipelines" tabindex="-1">Pipelines <a class="header-anchor" href="#pipelines" aria-label="Permalink to &quot;Pipelines&quot;">​</a></h1><p>A pipeline is a named run of OpenRouter calls. The log page lists each pipeline, then the sessions inside it, then the calls in a session.</p><p>You still send the calls with <code>@openrouter/agent</code> or <code>@openrouter/sdk</code>. Leo Logs supplies the trace id that makes those calls one pipeline. The package name is <code>leo-agent</code>.</p><h2 id="trace-id" tabindex="-1">Trace id <a class="header-anchor" href="#trace-id" aria-label="Permalink to &quot;Trace id&quot;">​</a></h2><p><code>createPipeline(name).sessionId()</code> returns <code>pipeline:{name}-execution:{uuid}</code>. The uuid is chosen once, so the id stays the same for that run. Put it on the OpenRouter request as <code>trace.traceId</code>.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createPipeline } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;leo-agent&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pipeline</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createPipeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;order-desk&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> traceId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sessionId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>A name may contain hyphens. It cannot contain <code>_agent:</code>.</p><p>Calls that use this id, and agent calls whose trace id starts with <code>{pipeline session id}_agent:</code>, belong to the same session.</p><p><code>examples/calls.ts</code> is one pipeline, <code>order-desk</code>, handling a late shipment. The agents inside it are <code>lookup</code>, <code>policy</code>, and <code>reply</code>.</p><h2 id="on-the-log-page" tabindex="-1">On the log page <a class="header-anchor" href="#on-the-log-page" aria-label="Permalink to &quot;On the log page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Address</th></tr></thead><tbody><tr><td>Pipelines</td><td><code>/</code></td></tr><tr><td>One pipeline</td><td><code>/sessions?pipeline=order-desk</code></td></tr><tr><td>One session</td><td><code>/session?pipeline=order-desk&amp;session=pipeline:order-desk-execution:…</code></td></tr></tbody></table><p><strong>Pipelines</strong> is one row per pipeline name. <strong>Avg cost</strong> is the mean cost of one session. <strong>P50 cost</strong>, <strong>P75 cost</strong>, <strong>P90 cost</strong>, and <strong>P95 cost</strong> are percentiles of those same session costs. <strong>Avg latency</strong> is the mean wall-clock time from the first call start to the last call end. <strong>Avg model time</strong> is the mean of each session&#39;s summed call durations. Overlapping calls both count in model time.</p><p><strong>Avg latency</strong>, <strong>Avg model time</strong>, and the four cost percentiles start hidden. Turn them on from <strong>Columns</strong>.</p><p>The Agents count opens a side panel of the agents in that pipeline.</p><p><strong>One pipeline</strong> lists sessions. <strong>Latency</strong> is that session&#39;s wall-clock span. <strong>Model time</strong> is the sum of its call durations. Those two columns start hidden. Stats above the table include input, output, and cached tokens, plus the same cost percentiles for the sessions on screen.</p><p><strong>One session</strong> lists that session&#39;s model calls, including its agents. <strong>Latency</strong> on a call is that call&#39;s duration. A row opens the messages panel. Functions and Server open the function-call panel. A function result is joined back to the original call by call id, so the panel can show the description and schema.</p><p>Shared filters, on this page and on Agents:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Meaning</th></tr></thead><tbody><tr><td><code>window</code></td><td><code>hour</code>, <code>day</code>, <code>week</code>, or <code>month</code>. Omitted means the past 30 days.</td></tr><tr><td><code>model</code></td><td>Repeat for each selected model.</td></tr><tr><td><code>q</code></td><td>Name filter.</td></tr><tr><td><code>failures</code></td><td><code>1</code> shows rows with failures only.</td></tr></tbody></table>`,18)])])}const k=s(a,[["render",o]]);export{g as __pageData,k as default};
